package com.nvv.mediadata.data.model.tmdbimport com.nvv.mediadata.data.utils.LocalDateSerializerimport kotlinx.serialization.SerialNameimport kotlinx.serialization.Serializableimport java.time.LocalDate@Serializabledata class Season(	@SerialName("air_date")	@Serializable(with = LocalDateSerializer::class)	val airDate: LocalDate? = null,	@SerialName("episode_count")	val episodeCount: Int = 0,	@SerialName("id")	val id: Long = -1,	@SerialName("name")	val name: String = "",	@SerialName("overview")	val overview: String = "",	@SerialName("poster_path")	val poster: String? = null,)